#!/usr/bin/env node
// This file is managed by Lisa and IS replaced on each `lisa` run.
// Do not edit directly — durable changes belong upstream in Lisa.
/**
 * Refuse a commit that stages a NEW file byte-identical to uncommitted work
 * living in a different linked worktree.
 *
 * WHAT THIS IS FOR. When several agents share one repository through linked
 * worktrees, one agent's uncommitted file can be committed by another — the
 * file is real, the branch is real, the commit succeeds, every gate passes,
 * and the history is quietly wrong about who did what. One confirmed case:
 * a 284-line test file staged in one worktree was committed an hour later
 * from elsewhere, byte-identical, under a subtly different subject line.
 *
 * WHY IT MUST BE A HOOK AND NOT A HABIT. The failure mode is that nobody
 * notices. A check an agent has to remember to run is a check that does not
 * run on the commit where it mattered. This runs on every commit, needs no
 * cooperation, and costs one `stat` per linked worktree per newly added file.
 *
 * WHY CONTENT AND NOT MESSAGE. The observed case had a rewritten subject
 * line, so anything keyed on the message would have missed it. Blob identity
 * cannot be edited away.
 *
 * THE LIMIT, STATED PLAINLY. This needs BOTH halves — the file being staged
 * here and the original still present over there. Once the other worktree is
 * removed, the comparison has nothing to match against and this guard is
 * silent. A clean run is therefore not proof that no work was taken; it is
 * proof that none is takeable *right now*. Deleting a worktree that holds
 * uncommitted work permanently forecloses the only window in which its own
 * case was detectable.
 *
 * That limit is now held open from the other end by
 * `lisa-worktree-guard.mjs` (CodySwannGT/lisa#3863), which refuses to remove a
 * worktree whose uncommitted bytes exist in no commit. The two are one control
 * read in two directions: this file needs the original to still be there, and
 * that one is what keeps it there.
 */

import { execFileSync } from "node:child_process";
import { existsSync, statSync } from "node:fs";
import { join } from "node:path";

/**
 * Paths that are ambient session furniture rather than authored work.
 *
 * Matched with `startsWith` rather than a constructed RegExp: a literal prefix
 * needs no pattern, and building one invites escaping that the shipped fixer
 * then rewrites, which makes this file stop being a fixed point of Lisa's own
 * formatter (#2788).
 */
const IGNORED_PREFIXES = [".codex/"];

/**
 * Content below this many bytes is not evidence of anything. A short or empty
 * file collides across worktrees by coincidence — an empty `__init__`, a
 * one-line barrel re-export, a placeholder — and a guard that fires on those
 * teaches people to bypass it, which costs more than the cases it would catch.
 */
const MIN_INTERESTING_BYTES = 64;

/**
 * Header markers that identify a file as GENERATED rather than authored.
 *
 * Two agents running the same deterministic generator against the same source
 * produce byte-identical output, in different worktrees, that is not yet on the
 * integration branch. That is this guard's trigger condition exactly — and it
 * is legitimate concurrent work rather than one agent taking another's.
 *
 * Measured against the real repository with two worktrees and the real
 * generators: for an artifact that already EXISTS on the integration branch the
 * case is excluded twice over — a regenerated file stages as a modification,
 * not an addition, and it is tracked in the other worktree. Disabling either
 * clause alone still accepted; only disabling BOTH made it refuse, which is how
 * that redundancy was established rather than assumed.
 *
 * A generator that emits a file NOT yet on the integration branch has neither
 * protection: it stages as an addition here and sits untracked over there. That
 * case was reproduced and DID refuse, so this marker check is what closes it.
 *
 * Keyed on the file's own declaration rather than on a path list, because the
 * distinction that matters is "identical because both were generated from the
 * same source" versus "identical because it is the same authored file" — and a
 * generated file says so at the top. A path list would need updating every time
 * a generator learns a new output, and would be wrong silently until it was.
 */
const GENERATED_MARKERS = Object.freeze([
  "@generated",
  "Generated by",
  "DO NOT EDIT",
  "Do not edit",
  "managed by Lisa",
]);

/**
 * How far into a file the declaration must appear.
 *
 * A generated file announces itself in its header. Scanning the whole file
 * would let the words "do not edit" occurring in ordinary prose — a rule, a
 * skill, a comment quoting a banner — silence the guard for an authored file.
 */
const GENERATED_HEADER_BYTES = 2048;

/**
 * Run a command, returning its trimmed stdout, or `null` when it exits
 * non-zero. Used for probes whose failure is a legitimate answer ("this path
 * is not on main", "this path is not tracked there") rather than an error.
 */
function probe(args, cwd) {
  try {
    return execFileSync("git", args, {
      cwd,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
    }).trim();
  } catch {
    // probe-direction: fail-closed — every consumer reads null as "not proven
    // safe": `isIntegrationContent` and `declaresItselfGenerated` return false,
    // and `integrationRef` yields null, each of which makes the guard FIRE.
    // A git that cannot answer costs a false report, never a silent pass.
    return null;
  }
}

function must(args, cwd) {
  return execFileSync("git", args, {
    cwd,
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
  }).trim();
}

/** Absolute paths of every registered linked worktree, this one included. */
function worktrees(repo) {
  const out = probe(["worktree", "list", "--porcelain"], repo) ?? "";
  return out
    .split("\n")
    .filter(line => line.startsWith("worktree "))
    .map(line => line.slice("worktree ".length).trim())
    .filter(Boolean);
}

/**
 * Paths staged as ADDED in this commit.
 *
 * Deliberately only `A`. A modified tracked file is frequently identical
 * across worktrees for honest reasons — a regenerated manifest is the common
 * one, and it is deterministic, so two agents regenerating it produce the same
 * bytes while differing from main. Firing on that would make the guard noise
 * on nearly every commit. A brand-new file with identical content in two
 * worktrees has no such innocent explanation.
 */
function stagedAdditions(repo) {
  const out = probe(
    ["diff", "--cached", "--name-only", "--diff-filter=A", "-z"],
    repo
  );
  if (out === null) return [];
  return out.split("\0").filter(Boolean);
}

/** The blob this commit is staging for `path`, or null when unreadable. */
function stagedBlob(repo, path) {
  return probe(["rev-parse", `:${path}`], repo);
}

/**
 * Whether `blob` is simply what the integration branch already holds at
 * `path`.
 *
 * THIS IS THE REJECTION CONTROL, and without it the guard is worthless rather
 * than merely weak. Measured while designing this: a first pass without it
 * fired on four files in one worktree that were byte-identical to `origin/main`
 * — content every worktree carries for the ordinary reason. A guard that
 * reports shared history as contamination fires on every worktree and is
 * switched off within the hour.
 */
function isIntegrationContent(repo, defaultRef, path, blob) {
  if (!defaultRef) return false;
  return probe(["rev-parse", `${defaultRef}:${path}`], repo) === blob;
}

/**
 * Whether the blob's header declares it generated.
 * @param {string} repo Repository root.
 * @param {string} blob Blob sha to read.
 * @returns {boolean} True when a generated marker appears in the header.
 */
function declaresItselfGenerated(repo, blob) {
  const body = probe(["cat-file", "blob", blob], repo);
  if (body === null) return false;
  const header = body.slice(0, GENERATED_HEADER_BYTES);
  return GENERATED_MARKERS.some(marker => header.includes(marker));
}

/** The remote-tracking integration ref, or null when it cannot be resolved. */
function integrationRef(repo) {
  const symref = probe(
    ["symbolic-ref", "--quiet", "refs/remotes/origin/HEAD"],
    repo
  );
  if (symref) return symref.replace(/^refs\/remotes\//, "");
  for (const candidate of ["origin/main", "origin/master"]) {
    if (probe(["rev-parse", "--verify", "--quiet", candidate], repo))
      return candidate;
  }
  return null;
}

/**
 * Paths the operator has explicitly cleared, as a comma-separated list.
 *
 * Deliberately path-scoped rather than a boolean. A blanket "off" switch on a
 * guard like this gets set once, in frustration, and never unset — and the
 * next real case passes silently. Naming the file keeps the override as narrow
 * as the situation that justified it.
 */
function clearedPaths() {
  const raw = process.env.LISA_ALLOW_CROSS_WORKTREE_BLOB;
  if (!raw) return new Set();
  return new Set(
    raw
      .split(",")
      .map(entry => entry.trim())
      .filter(Boolean)
  );
}

function findCollisions(repo, self) {
  const additions = stagedAdditions(repo);
  if (additions.length === 0) return [];

  const others = worktrees(repo).filter(tree => tree !== self);
  if (others.length === 0) return [];

  const defaultRef = integrationRef(repo);
  const cleared = clearedPaths();
  const collisions = [];

  for (const path of additions) {
    if (cleared.has(path)) continue;
    if (IGNORED_PREFIXES.some(prefix => path.startsWith(prefix))) continue;

    const blob = stagedBlob(repo, path);
    if (!blob) continue;

    const size = Number(probe(["cat-file", "-s", blob], repo));
    if (!Number.isFinite(size) || size < MIN_INTERESTING_BYTES) continue;

    if (isIntegrationContent(repo, defaultRef, path, blob)) continue;

    if (declaresItselfGenerated(repo, blob)) continue;

    for (const tree of others) {
      const candidate = join(tree, path);
      // The stat is the cheap filter: almost every worktree lacks the path,
      // so almost every pair costs one failed stat and nothing else.
      if (!existsSync(candidate)) continue;
      let stats;
      try {
        stats = statSync(candidate);
      } catch {
        continue;
      }
      if (!stats.isFile()) continue;

      const theirs = probe(["hash-object", candidate], repo);
      if (theirs !== blob) continue;

      // Tracked over there means it is shared history reaching that worktree
      // through a branch, not that agent's work in progress.
      const tracked = probe(["-C", tree, "ls-files", "--error-unmatch", path]);
      if (tracked !== null) continue;

      collisions.push({ path, tree });
      break;
    }
  }

  return collisions;
}

function report(collisions) {
  const lines = [
    "",
    "❌ Commit blocked: staged content is also uncommitted in another worktree.",
    "",
  ];
  for (const { path, tree } of collisions) {
    lines.push(`   ${path}`);
    lines.push(`     byte-identical to an uncommitted copy in ${tree}`);
  }
  lines.push("");
  lines.push("   Each file above is being added here while the same bytes sit");
  lines.push(
    "   uncommitted in another worktree. Either another agent authored it and"
  );
  lines.push(
    "   this commit would take credit for work in progress, or the same work"
  );
  lines.push("   is about to land twice on two branches.");
  lines.push("");
  lines.push("   Before retrying, establish which worktree authored it:");
  lines.push(
    "     git log --all --oneline --find-object=$(git rev-parse :<path>)"
  );
  lines.push(
    "   Inspect the other branch through shared refs — git log, git show,"
  );
  lines.push(
    "   git cat-file all reach it from here. Do NOT enter another agent's"
  );
  lines.push(
    "   working tree, and do not delete it: it may hold the only copy."
  );
  lines.push("");
  lines.push("   If this really is your own file, clear it by name:");
  lines.push(
    `     LISA_ALLOW_CROSS_WORKTREE_BLOB='${collisions.map(c => c.path).join(",")}' git commit ...`
  );
  lines.push("");
  return lines.join("\n");
}

function main() {
  let repo;
  let self;
  try {
    repo = must(["rev-parse", "--show-toplevel"]);
    self = repo;
  } catch {
    // Not a git repository, or git is unavailable. A commit is not happening
    // here in any case; there is nothing for this guard to say.
    return 0;
  }

  const collisions = findCollisions(repo, self);
  if (collisions.length === 0) return 0;

  process.stderr.write(report(collisions));
  return 1;
}

process.exit(main());
